const items = $input.all().map((item) => item.json);

const uniqueItems = items.reduce((acc, item) => {
  const { Type, Source, ["version-date"]: versionDate } = item.metadata;
  const key = `${Type}-${Source}-${versionDate}`;
  if (!acc[key]) {
    acc[key] = { Type, Source, "version-date": versionDate };
  }
  return acc;
}, {});

return Object.values(uniqueItems);

